import type { Loc } from '../i18n/format';
import type { ModuleId, SimulatorId } from './modules';
import type { FixedQuestion } from './questions/types';

export interface LectureLesson {
  id: string;
  pages: number[];
  module: ModuleId;
  simulator: SimulatorId;
  title: Loc;
  text: Loc;
  formula?: string;
  experiment: Loc;
  question: FixedQuestion;
}

const L = (de: string, ru: string): Loc => ({ de, ru });
function lesson(id: string, pages: number[], module: ModuleId, simulator: SimulatorId, title: Loc, text: Loc, formula: string | undefined, experiment: Loc, prompt: Loc, correct: Loc, wrong: Loc[], explanation: Loc): LectureLesson {
  return { id, pages, module, simulator, title, text, formula, experiment, question: { id: `mbr-${id}`, kind: 'mc', difficulty: 2, prompt, options: [correct, ...wrong], answer: 0, explanation, hint: experiment } };
}

